<template>
  <section class="menu-recipe-variant" v-loading="loading" :data-variant-id="activeId" :aria-label="'规格明细 · '+(variant.spec || '默认规格')">
    <header class="item-recipe-toolbar"><div class="variant-title"><span class="variant-label">规格</span><h4>{{ variant.spec || '默认规格' }}</h4><small v-if="variant.skuid">SKU {{ variant.skuid }}</small></div><div class="item-toolbar-actions"><span v-if="dirty" class="dirty-note">未保存</span><el-button type="primary" :loading="saving" :disabled="!dirty" @click="save">保存成本</el-button></div></header>
    <div v-if="variant.dine_in_price != null" class="variant-sale-prices"><span>堂食售价 <b>{{ amount(variant.dine_in_price) }}</b></span><span>会员价 <b>{{ variant.member_price > 0 ? amount(variant.member_price) : '未设置' }}</b></span></div>
    <p v-if="error" class="recipe-panel-error" role="alert">{{ error }}</p>
    <template v-if="draft">
      <div class="item-cost-summary"><div><span>单份食材成本</span><strong>{{ amount(foodCost) }}</strong></div><div><span>打包增加包材</span><strong>{{ draft.packaging_status === 'pending' ? '待设置' : amount(packedSupplyCost) }}</strong></div><div><span>打包后成本 / 份</span><strong>{{ amount(packedTotal) }}</strong></div></div>
      <div class="recipe-detail-layout">
      <div class="variant-food-editor"><h5 class="variant-section-heading">食材构成</h5>
        <div class="cost-mode-row"><el-radio-group v-model="draft.cost_mode" aria-label="成本录入方式"><el-radio-button value="manual">直接录入成本</el-radio-button><el-radio-button value="recipe">按明细组合计算</el-radio-button></el-radio-group></div>
        <el-form v-if="draft.cost_mode === 'manual'" label-position="top" class="direct-cost-form"><el-form-item label="单份食材成本（元，不含包材）" required><el-input-number :model-value="moneyNumber(draft.manual_food_cost)" @update:model-value="v => draft.manual_food_cost=moneyNumber(v)" :min="0" inputmode="decimal" :controls="false" aria-label="单份食材成本" /></el-form-item><p>包材按下方统一方案另计，避免把打包费用重复计入食材成本。</p></el-form>
        <template v-else>
          <div class="composition-tools"><el-select v-if="draft.source_choices?.length" placeholder="同名成本卡有多个版本，可选择带入明细" aria-label="带入原卡明细" @update:model-value="applySource"><el-option v-for="s in draft.source_choices" :key="s.id" :value="s.id" :label="s.name + ' · ' + s.variant" /></el-select><span v-else>用量按菜品维护，单位成本由通用食材统一管理。</span><el-button plain @click="addLine">添加构成</el-button></div>
          <div class="item-recipe-table-wrap"><table class="item-recipe-table"><colgroup><col style="width:32%"><col style="width:17%"><col style="width:8%"><col style="width:17%"><col style="width:13%"><col style="width:13%"></colgroup><thead><tr><th>食材 / 通用标准</th><th class="numeric">用量</th><th>单位</th><th class="numeric">统一单位成本</th><th class="numeric">本项成本</th><th class="numeric">操作</th></tr></thead><tbody><tr v-for="(l,i) in pageLines" :key="lineStart+i"><td><el-select v-model="l.material_id" filterable placeholder="选择食材" :aria-label="`构成${lineStart+i+1}食材`" @update:model-value="id => changeIngredient(l,id)"><el-option v-for="m in content.ingredients" :key="m.id" :label="materialLabel(m)" :value="m.id" /></el-select></td><td><el-input-number :model-value="l.quantity" @update:model-value="v => l.quantity=quantityValue(v)" :min="0.01" :step="1" inputmode="decimal" :controls="false" :aria-label="`构成${lineStart+i+1}用量`" /></td><td>{{ material(l.material_id)?.unit || '—' }}</td><td class="numeric">{{ price(material(l.material_id)?.unit_cost) }}</td><td class="numeric">{{ moneyText(lineCost(l),'待补') }}</td><td class="line-actions"><el-button link type="primary" :disabled="!l.material_id" @click="ingredientId=l.material_id">标准</el-button><el-button link type="danger" @click="draft.lines.splice(lineStart+i,1)">移除</el-button></td></tr></tbody></table></div>
          <el-pagination v-if="draft.lines.length" v-model:current-page="linePage" v-model:page-size="lineSize" :page-sizes="[5,10,20]" :total="draft.lines.length" layout="total, sizes, prev, pager, next" class="cost-pagination" />
          <el-empty v-else description="添加通用食材并填写用量，也可切换为直接录入成本" :image-size="45" />
        </template>
        <p v-if="alwaysSupplies.length" class="recipe-source-note">每次出品耗材：{{ alwaysSupplies.map(p => `${packageName(p.material_id)} × ${p.quantity}`).join('、') }}，单独计算，不重复计入食材。</p>
        <el-collapse v-if="draft.source" class="recipe-source-fold"><el-collapse-item title="查看原卡来源" name="source"><p class="recipe-source-note">{{ draft.source }}。原卡数据作为初始明细，保存后直接归当前菜品规格维护。</p></el-collapse-item></el-collapse>
      </div>
      <aside class="item-packing-editor"><h5 class="variant-section-heading">打包方案与试算</h5>
        <p class="packing-rule">堂食、团购打包与外卖共用同一方案；外卖自动打包。这里计算实际包材成本，向顾客收取的打包费另行核算。</p>
        <el-form label-position="top"><el-form-item label="当前菜品的打包方案"><el-select :model-value="schemeSelection" filterable aria-label="菜品打包方案" @update:model-value="setScheme"><el-option label="待设置打包方案" value="pending" /><el-option label="已确认无需额外包材" value="none" /><el-option v-for="s in content.packaging_schemes" :key="s.id" :value="s.id" :label="`${s.code ? s.code + ' · ' : ''}${s.name} · ${amount(s.unit_cost)}`" /></el-select></el-form-item></el-form>
        <div v-if="scheme" class="scheme-summary"><span>方案包材成本 <strong>{{ amount(scheme.unit_cost) }}</strong></span><el-button link type="primary" @click="schemeEditor=true">编辑共用方案</el-button></div>
        <section class="item-order-quote"><h4>订单成本试算</h4><div class="quote-controls"><el-select v-model="scenario.channel" aria-label="试算渠道"><el-option label="堂食" value="dine_in" /><el-option label="团购" value="group_buy" /><el-option label="外卖" value="delivery" /></el-select><el-input-number v-model="scenario.quantity" :min="1" :max="999" :precision="0" aria-label="试算份数" /><el-switch v-model="scenario.packed" :disabled="scenario.channel==='delivery'" aria-label="顾客打包" :active-text="scenario.channel==='delivery'?'外卖必须打包':'顾客打包'" /></div><p v-if="quoteError" class="recipe-panel-error">{{ quoteError }}</p><div class="quote-results" :class="{pending:quoting}"><span>食材 {{ amount(quote?.food_cost) }}</span><span>耗材及包材 {{ amount(quote?.packaging_cost) }}</span><strong>合计 {{ quote?.complete ? amount(quote.total_cost) : '成本待补齐' }}</strong></div><p v-if="quote?.missing.length" class="recipe-source-note">{{ [...new Set(quote.missing.map(m=>m.reason))].join('；') }}</p></section>
      </aside>
      </div>
    </template>
    <MenuIngredientEditor :material-id="ingredientId" :ingredients="content?.ingredients || []" @close="ingredientId=''" @saved="reloadStandards" />
    <MenuPackagingSchemeEditor :scheme="schemeEditor ? scheme : null" :materials="content?.packaging_materials || []" @close="schemeEditor=false" @saved="reloadStandards" />

  </section>
</template>
<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import { menuCostRecipesApi as api } from '@/api'
import MenuIngredientEditor from './MenuIngredientEditor.vue'
import { quantityValue } from './quantityInput'
import { moneyAmount, moneyText, moneyNumber } from './moneyDisplay'
import MenuPackagingSchemeEditor from './MenuPackagingSchemeEditor.vue'
const props=defineProps({variant:{type:Object,required:true}}),emit=defineEmits(['saved','state'])
const activeId=computed(()=>props.variant.sourceId),content=ref(null),draft=ref(null),initial=ref(''),error=ref(''),loading=ref(false),saving=ref(false),ingredientId=ref(''),schemeEditor=ref(false)
const linePage=ref(1),lineSize=ref(5),scenario=ref({channel:'dine_in',packed:false,quantity:1}),quote=ref(null),quoteError=ref(''),quoting=ref(false)
let request=0,timer,quoteRequest=0
const dirty=computed(()=>!!draft.value&&JSON.stringify(draft.value)!==initial.value)
const material=id=>content.value?.ingredients.find(m=>m.id===id),packageMaterial=id=>content.value?.packaging_materials.find(m=>m.id===id),packageName=id=>packageMaterial(id)?.name || '包材待补'
const materialLabel=m=>m.name+(m.spec?' · '+m.spec:'')
const price=n=>moneyText(n,'待补')
const amount=n=>moneyAmount(n,'待补齐')
const lineStart=computed(()=>(linePage.value-1)*lineSize.value),pageLines=computed(()=>draft.value?.lines.slice(lineStart.value,lineStart.value+lineSize.value)||[])
const lineCost=l=>{const m=material(l.material_id);return m?.complete&&l.quantity!=null?m.unit_cost*l.quantity:null}
const foodCost=computed(()=>{if(!draft.value)return null;if(draft.value.cost_mode==='manual')return draft.value.manual_food_cost;if(!draft.value.lines.length||draft.value.lines.some(l=>lineCost(l)==null))return null;return draft.value.lines.reduce((s,l)=>s+lineCost(l),0)})
const scheme=computed(()=>content.value?.packaging_schemes.find(s=>s.id===draft.value?.packaging_scheme_id))
const schemeSelection=computed(()=>draft.value?.packaging_scheme_id || draft.value?.packaging_status || 'pending')
const alwaysSupplies=computed(()=>draft.value?.packaging.filter(p=>p.usage==='always')||[])
const alwaysCost=computed(()=>alwaysSupplies.value.reduce((sum,p)=>sum+p.quantity*(packageMaterial(p.material_id)?.unit_cost||0),0))
const packedSupplyCost=computed(()=>scheme.value?.unit_cost??(draft.value?.packaging_status==='none'?0:null))
const packedTotal=computed(()=>foodCost.value==null||packedSupplyCost.value==null?null:foodCost.value+alwaysCost.value+packedSupplyCost.value)
function setScheme(id){draft.value.packaging_scheme_id=['none','pending'].includes(id)?null:id;draft.value.packaging_status=['none','pending'].includes(id)?id:'configured';draft.value.packaging=draft.value.packaging.filter(p=>p.usage==='always')}
function changeIngredient(l,id){const m=material(id);if(l.unit!==m.unit)l.quantity=1;l.unit=m.unit;l.ingredient_name=m.name}
function addLine(){draft.value.lines.push({material_id:'',quantity:1,unit:'克'});linePage.value=Math.ceil(draft.value.lines.length/lineSize.value)}
function applySource(id){const s=draft.value.source_choices.find(s=>s.id===id);draft.value.lines=JSON.parse(JSON.stringify(s.lines));linePage.value=1}
async function load(){const current=++request;clearTimeout(timer);quoteRequest++;if(!activeId.value)return;loading.value=true;error.value='';try{const d=await api.dish(activeId.value);if(current===request){content.value=d;draft.value=JSON.parse(JSON.stringify(d.draft));initial.value=JSON.stringify(draft.value);quote.value=null}}catch(e){if(current===request)error.value=e.message}finally{if(current===request)loading.value=false}}
async function refreshStandards(){const d=await api.dish(activeId.value);if(!content.value)return;content.value.ingredients=d.ingredients;content.value.packaging_schemes=d.packaging_schemes;content.value.packaging_materials=d.packaging_materials;scheduleQuote()}
async function reloadStandards(){await refreshStandards();window.dispatchEvent(new Event('menu-cost-standards-changed'))}
async function save(){saving.value=true;error.value='';try{await api.saveDish(activeId.value,draft.value);await load();emit('saved');window.dispatchEvent(new Event('menu-cost-standards-changed'));ElMessage.success('当前菜品的成本与打包方案已保存')}catch(e){error.value=e.message}finally{saving.value=false}}
function scheduleQuote(){clearTimeout(timer);const current=++quoteRequest;if(!draft.value)return;quoting.value=true;timer=setTimeout(async()=>{try{const d=await api.quoteDish(activeId.value,{draft:draft.value,...scenario.value});if(current===quoteRequest){quote.value=d.quote;quoteError.value=''}}catch(e){if(current===quoteRequest){quote.value=null;quoteError.value=e.message}}finally{if(current===quoteRequest)quoting.value=false}},250)}
watch(activeId,load,{immediate:true})
watch([dirty,saving,loading,foodCost,packedSupplyCost,packedTotal],()=>emit('state',{id:activeId.value,dirty:dirty.value,saving:saving.value,loading:loading.value,food:foodCost.value,packing:packedSupplyCost.value,packed:packedTotal.value}),{immediate:true})
watch([draft,scenario],scheduleQuote,{deep:true})
watch(()=>scenario.value.channel,c=>{if(c==='delivery')scenario.value.packed=true})
watch([()=>draft.value?.lines.length,lineSize],()=>{linePage.value=Math.min(linePage.value,Math.max(1,Math.ceil((draft.value?.lines.length||0)/lineSize.value)))})
function externalRefresh(){if(saving.value)return;if(dirty.value)refreshStandards().catch(e=>error.value=e.message);else load()}
onMounted(()=>window.addEventListener('menu-cost-standards-changed',externalRefresh))
onBeforeUnmount(()=>{request++;quoteRequest++;clearTimeout(timer);window.removeEventListener('menu-cost-standards-changed',externalRefresh)})
defineExpose({isDirty:()=>dirty.value,isSaving:()=>saving.value})
</script>
<style scoped>
