l-button{font-size:12px}.line-actions .el-button+.el-button{margin-left:8px}.cost-pagination{justify-content:flex-end;margin:16px 0}.recipe-source-fold{margin-top:16px}.recipe-source-fold :deep(.el-collapse-item__header){color:#7e8da1;font-size:12px}.packing-rule{font-size:12px;line-height:1.9;color:#76869b;margin:10px 0 18px}.item-packing-editor>.el-form .el-select{width:100%}.scheme-summary{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:14px 16px;background:#f5f8fc;border-radius:6px;font-size:13px;color:#7c8b9f}.scheme-summary strong{margin-left:10px;font-size:18px;color:#2b5a90;font-variant-numeric:tabular-nums}.item-order-quote{border-top:1px solid #e6ebf2;margin-top:24px;padding-top:16px}.item-order-quote h4{font-size:14px;margin:0 0 16px}.quote-controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.quote-controls>.el-select{width:108px}.quote-controls>.el-input-number{width:110px}.quote-results{display:flex;gap:10px;flex-direction:column;margin-top:18px;padding:16px;background:#f4f7fb;font-size:13px}.quote-results strong{margin-left:0;color:#28558b}.pending{opacity:.5}.recipe-panel-error{color:#b55e3d;font-size:13px;line-height:1.8}@media(max-width:700px){.item-recipe-toolbar{flex-direction:column}.item-cost-summary{gap:5px}.item-cost-summary>div{padding:10px}.item-cost-summary strong{font-size:17px}.cost-pagination{justify-content:flex-start;overflow:auto}.cost-mode-row{align-items:flex-start;flex-direction:column}}
