mary strong{margin-top:0}.variant-sale-prices{gap:14px}.item-toolbar-actions{width:100%;justify-content:space-between}.variant-title small{overflow-wrap:anywhere}.composition-tools{flex-wrap:wrap}.composition-tools>span{max-width:100%}}
.item-cost-summary>div{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:12px}.item-cost-summary strong{margin-top:0;font-size:17px}@media(max-width:700px){.item-cost-summary{grid-template-columns:1fr}}
